html:
{% set is_draft = doc.docstatus == 0 %}
{% set is_approved = doc.ts_mr_status == 'Approved' %}
{% set is_issue = doc.material_request_type == 'Material Issue' %}
{% set is_transfer = doc.material_request_type == 'Material Transfer' %}
{% set slip_title = 'MATERIAL ISSUE SLIP' if is_issue else 'MATERIAL TRANSFER SLIP' %}
{% set slip_subtitle = 'Internal stock issue / consumption' if is_issue else 'Internal stock movement between warehouses' %}
{% set from_col = 'ISSUE FROM' if is_issue else 'FROM WAREHOUSE' %}
{% set requestor_full_name = frappe.db.get_value('User', doc.owner, 'full_name') if doc.owner else '' %}
{% set first_use = '' %}{% for it in doc.items %}{% if it.ts_delivery_location and not first_use %}{% set first_use = it.ts_delivery_location %}{% endif %}{% endfor %}
{% set approved_by_user = '' %}
{% for c in frappe.get_all('Comment', filters={'reference_doctype': 'Material Request', 'reference_name': doc.name, 'comment_type': 'Comment'}, fields=['comment_email', 'content'], order_by='creation desc', limit=10) %}
{% if 'Approved by' in (c.content or '') and not approved_by_user %}{% set approved_by_user = c.comment_email %}{% endif %}
{% endfor %}
{% set approved_by_full = frappe.db.get_value('User', approved_by_user, 'full_name') if approved_by_user else '' %}

<style>
@page { size: A4; margin: 6mm 8mm 6mm 8mm; }
body { font-family: Arial, sans-serif; font-size: 10px; color: #000; }
.bbpl-wrap { position: relative; }
.bbpl-header-table { width: 100%; border-collapse: collapse; border: none; padding: 0 0 6px 0; }
.bbpl-header-table td { border: none !important; padding: 0; vertical-align: middle; }
.bbpl-logo-cell { width: 110px; padding-left: 6px !important; }
.bbpl-logo-cell img { max-width: 95px; max-height: 75px; }
.bbpl-header-text { text-align: center; padding-right: 110px !important; }
.bbpl-header-bottom-rule { border-bottom: 2px solid #000; margin: 0 0 6px 0; height: 0; line-height: 0; }
.bbpl-cname { font-size: 20px; font-weight: bold; color: #000; letter-spacing: 0.5px; line-height: 1.2; }
.bbpl-caddr { font-size: 12px; font-weight: bold; text-decoration: underline; margin-top: 2px; }
.bbpl-cinfo { font-size: 10px; margin-top: 3px; color: #111; }
.bbpl-cinfo span { margin: 0 6px; }
.bbpl-title-block { text-align: center; margin: 6px 0 4px 0; }
.bbpl-draft-stamp { font-size: 13px; font-weight: bold; letter-spacing: 2px; margin-bottom: 2px; color: #cc0000; }
.bbpl-title { font-size: 18px; font-weight: bold; text-decoration: underline; letter-spacing: 1px; }
.bbpl-subtitle { font-size: 10px; color: #333; margin-top: 2px; }
.bbpl-info-table { width: 100%; border-collapse: collapse; margin: 4px 0 4px 0; }
.bbpl-info-table td { padding: 3px 6px; font-size: 11px; vertical-align: middle; border: 1px solid #000; }
.bbpl-info-label { font-weight: bold; width: 22%; background: #eee; text-align: center; }
.bbpl-info-value { width: 28%; text-align: center; }
.bbpl-items { width: 100%; border-collapse: collapse; margin: 4px 0 0 0; }
.bbpl-items th { background: #e8e8e8; border: 1px solid #000; padding: 4px 5px; font-size: 10px; text-align: center; font-weight: bold; }
.bbpl-items td { border: 1px solid #000; padding: 3px 6px; font-size: 10px; vertical-align: top; }
.bbpl-items .num { text-align: right; }
.bbpl-items .ctr { text-align: center; }
.bbpl-section-heading { font-size: 12px; font-weight: bold; text-decoration: underline; margin: 8px 0 3px; }
.bbpl-notes-body { font-size: 11px; line-height: 1.5; padding: 4px; border: 1px solid #888; background: #fafafa; min-height: 24px; }
.bbpl-sign-table { width: 100%; border-collapse: collapse; margin: 18px 0 0 0; }
.bbpl-sign-table td { width: 50%; border: 1px solid #000; padding: 8px; vertical-align: top; height: 70px; }
.bbpl-sign-label { font-weight: bold; font-size: 11px; margin-bottom: 4px; }
.bbpl-sign-name { font-size: 10px; color: #333; margin-top: 4px; }
.bbpl-sign-line { border-top: 1px dotted #555; margin-top: 26px; padding-top: 2px; font-size: 9px; color: #666; }
.bbpl-footer { margin-top: 12px; border-top: 1px solid #000; padding-top: 5px; text-align: center; font-size: 10px; color: #111; line-height: 1.4; }
.bbpl-footer .fname { font-weight: bold; font-size: 11px; color: #000; }
.bbpl-watermark { position: fixed; top: 35%; left: 8%; font-size: 110px; color: rgba(255,0,0,0.08); font-weight: bold; transform: rotate(-30deg); -webkit-transform: rotate(-30deg); z-index: 0; letter-spacing: 18px; pointer-events: none; }
</style>

<div class="bbpl-wrap">

{% if is_draft %}<div class="bbpl-watermark">DRAFT</div>{% endif %}

<table class="bbpl-header-table">
<tr>
  <td class="bbpl-logo-cell">
    <img src="/files/client_logo.png" alt="BBPL" onerror="this.style.display='none'">
  </td>
  <td class="bbpl-header-text">
    <div class="bbpl-cname">BETUL BIOFUEL PVT LTD</div>
    <div class="bbpl-caddr">Bodi Junawani, Betul (M.P.)</div>
    <div class="bbpl-cinfo">
      <span><b>CIN:</b> U24110MP2021PTC05616</span>
      <span><b>GSTN:</b> 23AAJCB8781D1ZM</span>
    </div>
    <div class="bbpl-cinfo">
      <span><b>Email:</b> betulbiofuelpvtld@gmail.com</span>
      <span><b>Mobile no.:</b> 9823030102</span>
    </div>
  </td>
</tr>
</table>
<div class="bbpl-header-bottom-rule"></div>

<div class="bbpl-title-block">
  {% if is_draft %}<div class="bbpl-draft-stamp">DRAFT</div>{% endif %}
  <div class="bbpl-title">{{ slip_title }}</div>
  <div class="bbpl-subtitle">{{ slip_subtitle }}</div>
  <div class="bbpl-subtitle">Betul Biofuel Private Limited | Bodi Junawani, Betul (MP)</div>
</div>

<table class="bbpl-info-table">
<tr>
  <td class="bbpl-info-label">Request No</td>
  <td class="bbpl-info-value">{{ doc.name }}</td>
  <td class="bbpl-info-label">Date</td>
  <td class="bbpl-info-value">{{ frappe.format(doc.transaction_date, {'fieldtype': 'Date'}) }}</td>
</tr>
<tr>
  <td class="bbpl-info-label">Required By</td>
  <td class="bbpl-info-value">{{ frappe.format(doc.schedule_date, {'fieldtype': 'Date'}) if doc.schedule_date else '' }}</td>
  <td class="bbpl-info-label">Cost Center</td>
  <td class="bbpl-info-value">{{ doc.cost_center or '' }}</td>
</tr>
<tr>
  <td class="bbpl-info-label">Requested By</td>
  <td class="bbpl-info-value">{{ requestor_full_name or doc.owner or '' }}</td>
  <td class="bbpl-info-label">Approved By</td>
  <td class="bbpl-info-value">{{ approved_by_full or (approved_by_user or '—') }}</td>
</tr>
<tr>
  <td class="bbpl-info-label">Status</td>
  <td class="bbpl-info-value"><b>{{ doc.ts_mr_status or doc.status or '' }}</b></td>
  <td class="bbpl-info-label">Use Location</td>
  <td class="bbpl-info-value">{{ first_use or '' }}</td>
</tr>
</table>

<table class="bbpl-items">
<thead>
<tr>
  <th style="width:30px">S.NO</th>
  <th style="width:80px">ITEM CODE</th>
  <th>ITEM NAME</th>
  <th style="width:50px">QTY</th>
  <th style="width:45px">UOM</th>
  <th>SERIAL NO</th>
  <th>{{ from_col }}</th>
  <th>{% if is_issue %}USE LOCATION{% else %}TO LOCATION{% endif %}</th>
</tr>
</thead>
<tbody>
{% for item in doc.items %}
<tr>
  <td class="ctr">{{ loop.index }}</td>
  <td>{{ item.item_code or '' }}</td>
  <td>{{ item.item_name or '' }}</td>
  <td class="num">{{ frappe.format(item.qty, {'fieldtype': 'Float', 'precision': 0}) }}</td>
  <td class="ctr">{{ item.uom or item.stock_uom or '' }}</td>
  <td>{{ item.serial_no or '' }}</td>
  <td>{% if is_issue %}{{ item.warehouse or '' }}{% else %}{{ item.from_warehouse or '' }}{% endif %}</td>
  <td>{{ item.ts_delivery_location or '' }}</td>
</tr>
{% endfor %}
</tbody>
</table>

{% if doc.ts_transfer_remark %}
<div class="bbpl-section-heading">{% if is_issue %}Issue Remark / Notes{% else %}Transfer Remark / Notes{% endif %}</div>
<div class="bbpl-notes-body">{{ doc.ts_transfer_remark | safe }}</div>
{% endif %}

<table class="bbpl-sign-table">
<tr>
  <td>
    <div class="bbpl-sign-label">Requested By</div>
    <div class="bbpl-sign-line">Signature</div>
    <div class="bbpl-sign-name">{{ requestor_full_name or doc.owner or '' }}</div>
  </td>
  <td>
    <div class="bbpl-sign-label">Approved By Stores Manager</div>
    <div class="bbpl-sign-line">Signature</div>
    <div class="bbpl-sign-name">{% if is_approved %}{{ approved_by_full or approved_by_user or '' }}{% else %}—{% endif %}</div>
  </td>
</tr>
</table>

<div class="bbpl-footer">
  <div class="fname">BETUL BIOFUEL PVT LTD</div>
  <div>Bodi Junawani, Betul (M.P.)</div>
  <div>CIN; U24110MP2021PTC05616 &nbsp;&nbsp; GSTN: 23AAJCB8781D1ZM</div>
  <div>Email: betulbiofuelpvtld@gmail.com &nbsp;&nbsp; Mobile no.- 9823030102</div>
</div>

</div>
